func TestOperatorAgentSendDirectivePersistsDirectiveEventOnceOnReplay(t *testing.T) {
	_, db, cleanup := testutil.StartPostgres(t)
	t.Cleanup(cleanup)
	pg := storetest.AdmitPostgresRuntimeStore(t, db)
	workOwner := newAPITestRuntimeWorkOccurrence(t, authorActivityTestRuntimeInstanceID, authorActivityTestSourceArtifactFact.BundleHash())
	bus, err := newScopedAPITestEventBus(t, pg, runtimebus.EventBusOptions{WorkOwner: workOwner})
	if err != nil {
		t.Fatalf("NewEventBus: %v", err)
	}
	agent := &directiveIntegrationAgent{id: "agent-1"}
	manager := runtimemanager.NewAgentManagerWithOptions(bus, func(cfg runtimeactors.AgentConfig) (runtimemanager.Agent, error) {
		return agent, nil
	}, runtimemanager.AgentManagerOptions{ExecutionPosture: executionposture.Live, BaseContext: testAuthorActivityContext(context.Background()), WorkOwner: workOwner, PersistenceRoles: runtimemanager.PersistenceRoles{DirectiveOperations: pg, DirectiveTargets: pg}, ReceiverExecution: eventreceiver.NormalExecution(), LifecycleStore: storetest.AgentLifecycleFixture(t, pg)}, pg)
	t.Cleanup(func() {
		if err := manager.Shutdown(); err != nil {
			t.Errorf("shutdown directive integration manager: %v", err)
		}
	})
	storetest.RequireRun(t, context.Background(), pg, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: agentidentitytest.DefaultRunID, BundleHash: authorActivityTestSourceArtifactFact.BundleHash()})
	materializeAPITestAgent(t, testAuthorActivityContext(context.Background()), pg, manager, withAPITestIntent(t, runtimeactors.AgentConfig{ExecutionMode: "live", ID: agent.id, Model: "regular", ResolvedLLMBackend: "anthropic"}))
	handler := testHandler(t, Options{AuthTokens: []string{testToken}, Handlers: testOperatorHandlers(testOperatorCapabilities{Idempotency: pg, AgentConversations: pg, AgentControl: manager})})
	body := agentDirectiveBody("agent-1", "run corpus", "idem-directive-integration")
	first := rpcCall(t, handler, body)
	if first.Error != nil {
		t.Fatalf("first directive error = %#v", first.Error)
	}
	replay := rpcCall(t, handler, body)
	if replay.Error != nil {
		t.Fatalf("replay directive error = %#v", replay.Error)
	}
	if agent.calls != 1 {
		t.Fatalf("BoardStep calls = %d, want 1", agent.calls)
	}
	if count := countDirectiveEvents(t, pg); count != 1 {
		t.Fatalf("platform.agent_directive rows = %d, want 1", count)
	}
	conflict := rpcCall(t, handler, agentDirectiveBody("agent-1", "different", "idem-directive-integration"))
	if conflict.Error == nil {
		t.Fatal("conflict error = nil")
	}
	if agent.calls != 1 {
		t.Fatalf("BoardStep calls after conflict = %d, want 1", agent.calls)
	}
	if count := countDirectiveEvents(t, pg); count != 1 {
		t.Fatalf("platform.agent_directive rows after conflict = %d, want 1", count)
	}
}

