func TestDurableDataHTTPPublicSurfaceAcrossSelectedStores(t *testing.T) {
	for _, backend := range []struct {
		name string
		open func(*testing.T) dataHTTPSelectedStore
	}{{name: "sqlite", open: func(t *testing.T) dataHTTPSelectedStore {
		return storetest.StartSQLiteRuntimeStore(t)
	}}, {name: "postgres", open: func(t *testing.T) dataHTTPSelectedStore {
		_, db, _ := testutil.StartPostgres(t)
		return storetest.AdmitPostgresRuntimeStore(t, db)
	}}} {
		t.Run(backend.name, func(t *testing.T) {
			ctx := context.Background()
			selected := backend.open(t)
			db := storetest.Database(selected)
			catalog, ref := dataHTTPProbeCatalog(t)
			if _, err := selected.EnsureSourceArtifactWithData(ctx, dataProbeSourceArtifact, catalog); err != nil {
				t.Fatalf("register catalog: %v", err)
			}
			handler := testHandler(t, Options{AuthTokens: []string{testToken}, Handlers: OperatorDataHandlers(DataHandlerOptions{Store: selected})})
			call := func(method string, params map[string]any) map[string]any {
				t.Helper()
				status, response, body := callReadOnlyProbeRPC(t, handler, method, params, "Bearer "+testToken)
				if status != 200 || response.Error != nil {
					t.Fatalf("%s = status:%d error:%#v body:%s", method, status, response.Error, body)
				}
				return asMap(t, response.Result)
			}
			callError := func(method string, params map[string]any) *rpcError {
				t.Helper()
				status, response, body := callReadOnlyProbeRPC(t, handler, method, params, "Bearer "+testToken)
				if status != 200 || response.Error == nil {
					t.Fatalf("%s hostile call = status:%d response:%#v body:%s", method, status, response, body)
				}
				return response.Error
			}
			input := func(slug string) map[string]any {
				return map[string]any{"format": "jsonl", "content_base64": base64.StdEncoding.EncodeToString([]byte("{\"slug\":\"" + slug + "\"}\n"))}
			}
			declaration := map[string]any{"flow_path": ref.FlowPath, "event": ref.EventName}
			missingDeclaration := map[string]any{"flow_path": ref.FlowPath, "event": "missing.loaded"}
			for _, probe := range []map[string]any{{"view": "version", "declaration": missingDeclaration, "selector": map[string]any{"kind": "head"}}, {"view": "rows", "declaration": missingDeclaration, "selector": map[string]any{"kind": "head"}, "page": map[string]any{}}, {"view": "row", "declaration": missingDeclaration, "selector": map[string]any{"kind": "head"}, "row_selector": map[string]any{"position": 1}}, {"view": "export_chunk", "declaration": missingDeclaration, "selector": map[string]any{"kind": "head"}, "page": map[string]any{}}, {"view": "provenance", "declaration": missingDeclaration, "selector": map[string]any{"kind": "head"}, "page": map[string]any{}}, {"view": "pins", "declaration": missingDeclaration, "selector": map[string]any{"kind": "head"}, "page": map[string]any{}}} {
				if err := callError("data.show", probe); asMap(t, err.Data)["code"] != string(durabledata.CodeDeclarationMissing) {
					t.Fatalf("missing declaration error = %#v for %#v", err, probe)
				}
			}
			emptyCheck := call("data.check", map[string]any{"source_invocation_id": uuid.NewString(), "bundle_hash": dataProbeBundleHash, "declaration": declaration, "expected_head": map[string]any{"state": "absent"}, "input": map[string]any{"format": "jsonl", "content_base64": ""}})
			emptyCandidate := asMap(t, emptyCheck["candidate"])
			emptyManifest := asMap(t, emptyCandidate["manifest"])
			if emptyCheck["outcome"] != "accepted" || emptyCandidate["state"] != "candidate" || emptyCandidate["alias"] != nil || emptyManifest["row_count"] != float64(0) {
				t.Fatalf("empty JSONL check = %#v", emptyCheck)
			}
			first := call("data.import", map[string]any{"source_invocation_id": uuid.NewString(), "bundle_hash": dataProbeBundleHash, "declaration": declaration, "expected_head": map[string]any{"state": "absent"}, "input": input("alpha")})
			firstCandidate := asMap(t, first["candidate"])
			firstVersion := stringValue(t, firstCandidate["version_id"], "first version")
			if stringValue(t, first["outcome"], "first outcome") != "accepted" {
				t.Fatalf("first import = %#v", first)
			}
			staleCheck := call("data.check", map[string]any{"source_invocation_id": uuid.NewString(), "bundle_hash": dataProbeBundleHash, "declaration": declaration, "expected_head": map[string]any{"state": "absent"}, "input": input("stale")})
			staleCandidate := asMap(t, staleCheck["candidate"])
			if staleCheck["outcome"] != "head_conflict" || staleCandidate["state"] != "candidate" || staleCandidate["alias"] != nil {
				t.Fatalf("stale uncommitted candidate = %#v", staleCheck)
			}
			rows := call("data.show", map[string]any{"view": "rows", "declaration": declaration, "selector": map[string]any{"kind": "version", "version_id": firstVersion}, "page": map[string]any{}})
			if len(asSlice(t, rows["items"])) != 1 {
				t.Fatalf("rows = %#v", rows)
			}
			keyedRow := call("data.show", map[string]any{"view": "row", "declaration": declaration, "selector": map[string]any{"kind": "version", "version_id": firstVersion}, "row_selector": map[string]any{"key": "alpha"}})
			if keyedRow["key"] != "alpha" || keyedRow["ordinal"] != float64(1) {
				t.Fatalf("keyed row = %#v", keyedRow)
			}
			if err := callError("data.show", map[string]any{"view": "row", "declaration": declaration, "selector": map[string]any{"kind": "version", "version_id": firstVersion}, "row_selector": map[string]any{"position": 1}}); err.Code != codeInvalidParams {
				t.Fatalf("keyed position selector error = %#v", err)
			}
			keylessDeclaration := map[string]any{"flow_path": ".", "event": "score.observed"}
			keyless := call("data.import", map[string]any{"source_invocation_id": uuid.NewString(), "bundle_hash": dataProbeBundleHash, "declaration": keylessDeclaration, "expected_head": map[string]any{"state": "absent"}, "input": map[string]any{"format": "jsonl", "content_base64": base64.StdEncoding.EncodeToString([]byte("{\"label\":\"same\"}\n{\"label\":\"other\"}\n{\"label\":\"same\"}\n"))}})
			keylessVersion := stringValue(t, asMap(t, keyless["candidate"])["version_id"], "keyless version")
			positionalRow := call("data.show", map[string]any{"view": "row", "declaration": keylessDeclaration, "selector": map[string]any{"kind": "version", "version_id": keylessVersion}, "row_selector": map[string]any{"position": 2}})
			if positionalRow["ordinal"] != float64(2) || positionalRow["key"] != nil || asMap(t, positionalRow["value"])["label"] != "other" {
				t.Fatalf("keyless positional row = %#v", positionalRow)
			}
			if err := callError("data.show", map[string]any{"view": "row", "declaration": keylessDeclaration, "selector": map[string]any{"kind": "version", "version_id": keylessVersion}, "row_selector": map[string]any{"key": "same"}}); err.Code != codeInvalidParams {
				t.Fatalf("keyless business-key selector error = %#v", err)
			}
			second := call("data.import", map[string]any{"source_invocation_id": uuid.NewString(), "bundle_hash": dataProbeBundleHash, "declaration": declaration, "expected_head": map[string]any{"state": "version", "version_id": firstVersion}, "input": input("beta")})
			secondVersion := stringValue(t, asMap(t, second["candidate"])["version_id"], "second version")
			versionsPage := call("data.show", map[string]any{"view": "versions", "declaration": declaration, "page": map[string]any{"limit": 1}})
			versionItems := asSlice(t, versionsPage["items"])
			versionContinuation := asMap(t, versionsPage["continuation"])
			if len(versionItems) != 1 || versionContinuation["state"] != "more" {
				t.Fatalf("first selector-free versions page = %#v", versionsPage)
			}
			versionsPage = call("data.show", map[string]any{"view": "versions", "declaration": declaration, "page": map[string]any{"limit": 1, "cursor": versionContinuation["cursor"]}})
			versionItems = asSlice(t, versionsPage["items"])
			if len(versionItems) != 1 || stringValue(t, asMap(t, versionItems[0])["version_id"], "continued version") != secondVersion || asMap(t, versionsPage["continuation"])["state"] != "end" {
				t.Fatalf("second selector-free versions page = %#v", versionsPage)
			}
			corrupt := []byte("{\"slug\":")
			update := `UPDATE resource_versions SET canonical_jsonl = ? WHERE version_id = ?`
			if backend.name == "postgres" {
				update = `UPDATE resource_versions SET canonical_jsonl = $1 WHERE version_id = $2`
			}
			if _, err := db.ExecContext(ctx, update, corrupt, firstVersion); err != nil {
				t.Fatalf("corrupt sibling payload: %v", err)
			}
			selectedVersion := map[string]any{"kind": "version", "version_id": secondVersion}
			for _, probe := range []map[string]any{{"view": "version", "declaration": declaration, "selector": selectedVersion}, {"view": "rows", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "export_chunk", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "provenance", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "pins", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "head_history", "declaration": declaration, "page": map[string]any{}}} {
				call("data.show", probe)
			}
			if err := callError("data.show", map[string]any{"view": "rows", "declaration": declaration, "selector": map[string]any{"kind": "version", "version_id": firstVersion}, "page": map[string]any{}}); asMap(t, err.Data)["code"] != string(durabledata.CodeIntegrity) {
				t.Fatalf("corrupt selected payload error = %#v", err)
			}
			if _, err := db.ExecContext(ctx, update, []byte("{\"slug\":\"alpha\"}\n"), firstVersion); err != nil {
				t.Fatalf("restore sibling payload: %v", err)
			}
			pruned := call("data.prune", map[string]any{"prune_invocation_id": uuid.NewString(), "declaration": declaration, "version_id": firstVersion, "expected_head": map[string]any{"state": "version", "version_id": secondVersion}})
			if stringValue(t, pruned["outcome"], "prune outcome") != "pruned" {
				t.Fatalf("prune = %#v", pruned)
			}
		})
	}
}

