			for _, probe := range []map[string]any{{"view": "version", "declaration": declaration, "selector": selectedVersion}, {"view": "rows", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "export_chunk", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "provenance", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "pins", "declaration": declaration, "selector": selectedVersion, "page": map[string]any{}}, {"view": "head_history", "declaration": declaration, "page": map[string]any{}}} {
