		wantCode   string
		wantReason string
	}{{name: "blank target requires object", body: fmt.Sprintf(`{"jsonrpc":"2.0","id":"publish","method":"event.publish","params":{"bundle_hash":%q,"event_name":"operating/opco.product_initialization_requested","payload":{},"run_id":%q,"target":null,"idempotency_key":"idem-target-null"}}`, runStartTestBundleHash, runID), wantCode: "INVALID_PARAMS"}, {name: "missing flow instance", body: fmt.Sprintf(`{"jsonrpc":"2.0","id":"publish","method":"event.publish","params":{"bundle_hash":%q,"event_name":"operating/opco.product_initialization_requested","payload":{},"run_id":%q,"target":{"entity_id":%q},"idempotency_key":"idem-target-missing-flow"}}`, runStartTestBundleHash, runID, targetEntityID), wantCode: "INVALID_PARAMS"}, {name: "bad target entity uuid", body: fmt.Sprintf(`{"jsonrpc":"2.0","id":"publish","method":"event.publish","params":{"bundle_hash":%q,"event_name":"operating/opco.product_initialization_requested","payload":{},"run_id":%q,"target":{"flow_instance":"operating/inst-1","entity_id":"not-a-uuid"},"idempotency_key":"idem-target-bad-uuid"}}`, runStartTestBundleHash, runID), wantCode: "INVALID_PARAMS"}, {name: "entity id is not a flow instance address", body: fmt.Sprintf(`{"jsonrpc":"2.0","id":"publish","method":"event.publish","params":{"bundle_hash":%q,"event_name":"operating/opco.product_initialization_requested","payload":{},"run_id":%q,"target":{"flow_instance":%q,"entity_id":%q},"idempotency_key":"idem-target-entity-address"}}`, runStartTestBundleHash, runID, targetEntityID, targetEntityID), wantCode: "INVALID_PARAMS"}, {name: "nonexistent entity", body: eventPublishBodyWithTarget(runID, "", bundleHash, "operating/opco.product_initialization_requested", `{"topic":"missing-entity"}`, "operator-test", "idem-target-missing-entity", targetFlowInstance, uuid.NewString()), wantCode: EventNotDeclaredCode, wantReason: "selected_root_input_required"}, {name: "mismatched entity flow", body: eventPublishBodyWithTarget(runID, "", bundleHash, "operating/opco.product_initialization_requested", `{"topic":"mismatch"}`, "operator-test", "idem-target-mismatch", targetFlowInstance, mismatchEntityID), wantCode: EventNotDeclaredCode, wantReason: "selected_root_input_required"}, {name: "event not routable for target flow", body: eventPublishBodyWithTarget(runID, "", bundleHash, "operating/opco.product_initialization_requested", `{"topic":"unroutable"}`, "operator-test", "idem-target-unroutable", "orphan/inst-1", unroutableEntityID), wantCode: EventNotDeclaredCode, wantReason: "selected_root_input_required"}}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			resp := rpcCall(t, handler, tc.body)
			if resp.Error == nil {
				t.Fatal("event.publish error = nil")
			}
			if tc.wantCode == "INVALID_PARAMS" {
				if resp.Error.Code != codeInvalidParams {
					t.Fatalf("error code = %d, want %d; data=%#v", resp.Error.Code, codeInvalidParams, resp.Error.Data)
				}
				return
			}
			data := asMap(t, resp.Error.Data)
			if data["code"] != tc.wantCode {
				t.Fatalf("error data = %#v, want code %s", data, tc.wantCode)
			}
			if tc.wantReason != "" {
				details := asMap(t, data["details"])
				if details["reason"] != tc.wantReason {
					t.Fatalf("error details = %#v, want reason %s", details, tc.wantReason)
				}
			}
			if got := countEventRowsByRunID(t, pg, runID); got != 1 {
				t.Fatalf("events for selected run after rejected target = %d, want 1", got)
			}
			if got := countAPIIdempotencyRows(t, pg); got != 1 {
				t.Fatalf("api_idempotency rows after rejected target = %d, want 1", got)
			}
		})
	}
}

