func TestOpaqueMissingEventIDReturnsNotFoundAcrossOperatorConsumersParity(t *testing.T) {
	type fixture struct {
		store completeOperatorReplayProofStore
		db    *sql.DB
	}
	for _, tc := range []struct {
		name string
		open func(*testing.T, context.Context) fixture
	}{{name: "sqlite", open: func(t *testing.T, ctx context.Context) fixture {
		sqliteStore := storetest.StartSQLiteRuntimeStoreWithContext(t, ctx)
		return fixture{store: sqliteStore, db: storetest.DatabaseForTest(sqliteStore)}
	}}, {name: "postgres", open: func(t *testing.T, _ context.Context) fixture {
		_, db, cleanup := testutil.StartPostgres(t)
		t.Cleanup(cleanup)
		return fixture{store: storetest.AdmitPostgresRuntimeStore(t, db), db: db}
	}}} {
		t.Run(tc.name, func(t *testing.T) {
			ctx := testAuthorActivityContext(context.Background())
			f := tc.open(t, ctx)
			if _, err := f.store.EnsureSourceArtifactWithData(ctx, authorActivityTestSourceArtifact, durabledata.Catalog{BundleHash: runStartTestBundleHash}); err != nil {
				t.Fatalf("admit replay fixture source: %v", err)
			}
			seedActiveOperatorReplayAgent(t, ctx, f.store, "agent-a")
			if _, err := f.store.LoadOperatorEvent(ctx, "missing"); !errors.Is(err, operatorread.ErrEventNotFound) {
				t.Fatalf("operator reader error = %v, want ErrEventNotFound", err)
			}
			bus, err := newScopedAPITestEventBus(t, f.store, runtimebus.EventBusOptions{ContractBundle: semanticview.Wrap(runStartTestBundle("scan.requested"))})
			if err != nil {
				t.Fatalf("NewEventBusWithOptions: %v", err)
			}
			handler := completeOperatorReplayTestHandler(t, f.store, bus, time.Now().UTC())
			for _, method := range []struct {
				name string
				body string
			}{{name: "event.get", body: `{"jsonrpc":"2.0","id":"get","method":"event.get","params":{"event_id":"missing"}}`}, {name: "event.replay", body: eventReplayBody("missing", nil, "missing-event-replay")}, {name: "agent.replay", body: agentReplayBody("missing", "agent-a", "missing-agent-replay")}} {
				t.Run(method.name, func(t *testing.T) {
					response := rpcCall(t, handler, method.body)
					if response.Error == nil {
						t.Fatal("opaque missing event ID error = nil")
					}
					if data := asMap(t, response.Error.Data); data["code"] != EventNotFoundCode {
						t.Fatalf("opaque missing event ID data = %#v, want %s", data, EventNotFoundCode)
					}
				})
			}
			for _, table := range []string{"events", "event_deliveries", "api_idempotency"} {
				var count int
				if err := f.db.QueryRowContext(ctx, "SELECT COUNT(*) FROM "+table).Scan(&count); err != nil {
					t.Fatalf("count %s: %v", table, err)
				}
				if count != 0 {
					t.Fatalf("%s rows after opaque missing reads = %d, want 0", table, count)
				}
			}
		})
	}
}

