func seedReplayableOperatorEvent(t *testing.T, ctx context.Context, pg *store.PostgresStore, eventName string, subscribers []string, status runtimedelivery.Status) operatorread.OperatorEventFull {
	t.Helper()
	eventID := uuid.NewString()
	runID := operatorReplayRunID
	storetest.RequireRun(t, ctx, pg, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: runID})
	semanticEvent := eventtest.PersistedProjection(eventID, events.EventType(eventName), "origin-agent", "", []byte(`{"topic":"medicine"}`), 0, runID, "", events.EnvelopeForEntityID(events.EventEnvelope{}, runID), time.Now().UTC())
	routes := make([]events.DeliveryRoute, 0, len(subscribers))
	for _, subscriber := range subscribers {
		routes = append(routes, events.DeliveryRoute{Recipient: events.MustAgentDeliveryRecipient(subscriber), AgentIdentity: operatorReplayAgentIdentity(t, subscriber)})
	}
	scope := runtimepipelineobligation.ScopeDirect
	if len(routes) > 0 {
		scope = runtimepipelineobligation.ScopeSubscribed
	}
	storetest.CommitSemanticEventWithRoutes(t, ctx, pg, semanticEvent, routes, scope)
	for _, route := range routes {
		subscriber := route.Recipient.ID()
		switch status {
		case runtimedelivery.StatusPending:
			continue
		case runtimedelivery.StatusInProgress, runtimedelivery.StatusDelivered:
			claimed, err := storetest.ClaimDelivery(ctx, pg, semanticEvent, route)
			if err != nil {
				t.Fatalf("claim original delivery %s %s: %v", eventID, subscriber, err)
			}
			sessionID := seedOperatorReplayDeliverySession(t, ctx, pg, storetest.DatabaseForTest(pg), false, runID, route.AgentIdentity)
			if _, err := pg.BindAgentSession(ctx, claimed.Claim, sessionID); err != nil {
				t.Fatalf("bind original delivery %s %s: %v", eventID, subscriber, err)
			}
			if status == runtimedelivery.StatusDelivered {
				if _, err := pg.SettleSuccess(ctx, claimed.Claim, nil, 0, runtimedelivery.NotApplicableHandlerRuleSelection()); err != nil {
					t.Fatalf("settle original delivery %s %s: %v", eventID, subscriber, err)
				}
			}
		default:
			t.Fatalf("unsupported replay fixture delivery status %q", status)
		}
	}
	event, err := pg.LoadOperatorEvent(ctx, eventID)
	if err != nil {
		t.Fatalf("LoadOperatorEvent(%s): %v", eventID, err)
	}
	return event
}

