			deferred, err := storetest.DecisionCardDomain(cards).ApplyDeferralForTest(ctx, decisioncard.DeferRequest{CardID: card.CardID, PrincipalID: "operator", Until: deferredAt.Add(10 * time.Minute), Now: deferredAt})
			if err != nil {
				t.Fatalf("defer typed human-task card: %v", err)
