			decisionAt := deferredAt.Add(time.Second)
			decisionEventID := uuid.NewString()
			decided, err := storetest.DecisionCardDomain(cards).ApplyDecisionForTest(ctx, decisioncard.DecideRequest{CardID: card.CardID, Verdict: "approve", PrincipalID: "operator", ObservedContentHash: card.CardContentHash, DecisionEventID: decisionEventID, Now: decisionAt})
