		fixture         string
		eventName       string
		seedSourceTimer bool
		fanOutBarrier   bool
		wantCode        string
		wantCapability  string
	}{{name: "selected fan-out barrier has no deferred execution owner", fanOutBarrier: true, eventName: "items.ready", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkFanOutBarrier}, {name: "revisioned active source timer", fixture: "tests/tier5-flow-lifecycle/test-timer-fire", eventName: "timer.scheduled", seedSourceTimer: true, wantCode: runfork.RunForkBlockerTimerHistoryUnproven, wantCapability: selectedContractDeferredWorkRevisionTimerHistory}, {name: "selected handler can create workflow timer", fixture: "tests/tier5-flow-lifecycle/test-timer-fire", eventName: "timer.scheduled", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkWorkflowTimer}, {name: "selected handler can arm workflow join timeout", fixture: "examples/routing/fan-in/barrier", eventName: "portfolio.setup", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkWorkflowJoinTimeout}, {name: "selected connect can create dynamic flow", fixture: "examples/routing/template-create-minted-key", eventName: "validation.triggered", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkDynamicFlowCreation}, {name: "selected connect can select or create missing dynamic flow", fixture: "examples/routing/template-select-or-create", eventName: "producer/account.requested", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkDynamicFlowCreation}} {
		t.Run(test.name, func(t *testing.T) {
			_, db, _ := testutil.StartPostgres(t)
			pg := storetest.AdmitPostgresRuntimeStore(t, db)
			ctx := runForkTestContext(t)
			repoRoot := runForkExecutionRepoRoot(t)
			contractsRoot := filepath.Join(repoRoot, test.fixture)
			if test.fanOutBarrier {
				contractsRoot = canonicalrouting.CopyForkFanOutCarrier(t, false, true)
			}
			loader := admittedFixtureSelectedContractSourceLoader{RepoRoot: repoRoot, SourceRoot: contractsRoot, PlatformSpecPath: runtimecontracts.DefaultPlatformSpecFile(repoRoot)}
			sourceRunID := uuid.NewString()
			sourceEventID := uuid.NewString()
			at := time.Unix(1700002210, 0).UTC()
			entityID := uuid.NewString()
			seedSelectedExecutionSourceRunWithPrimaryRoute(t, db, sourceRunID, entityID, sourceEventID, test.eventName, at, "test_entity", selectedExecutionTestAgentRoute(t, sourceRunID, "source-agent-that-must-not-route", "flow-a/1"), nil)
			sourceTimerID := ""
			if test.seedSourceTimer {
				sourceTimerID = uuid.NewString()
				ref := timeridentity.WorkflowTimerActivationRef{ActivationID: sourceTimerID, DeclarationKey: "test-node.check_timer", DeclarationRevision: "sha256:test-node-check-timer", Cause: timeridentity.WorkflowTimerActivationCauseInitial}
				if _, err := db.ExecContext(ctx, `
					INSERT INTO timers (
						timer_id, run_id, timer_name, entity_id, flow_scope_key, flow_instance_id, flow_instance, fire_event,
						fire_payload, routing_source, execution_mode, fire_at, owner_agent, owner_kind, task_type, status, created_at
					)
					VALUES (
						$1::uuid, $2::uuid, $3, $4::uuid, 'flow-a', '1', 'flow-a/1', 'timer.check',
						'{}'::jsonb, jsonb_build_object('kind', 'flow_owned_control', 'route', jsonb_build_object('flow_id', 'flow-a', 'flow_instance', 'flow-a/1', 'entity_id', $4::text)),
						'live', $5, 'test-node', 'system', 'workflow_timer', 'active', $6
					)
				`, sourceTimerID, sourceRunID, ref.TaskID(), entityID, at.Add(time.Hour), at); err != nil {
					t.Fatalf("seed source workflow timer: %v", err)
				}
			}
