	}{{name: "selected fan-out barrier has no deferred execution owner", fanOutBarrier: true, eventName: "items.ready", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkFanOutBarrier}, {name: "revisioned active source timer", fixture: "tests/tier5-flow-lifecycle/test-timer-fire", eventName: "timer.scheduled", seedSourceTimer: true, wantCode: runfork.RunForkBlockerTimerHistoryUnproven, wantCapability: selectedContractDeferredWorkRevisionTimerHistory}, {name: "selected handler can create workflow timer", fixture: "tests/tier5-flow-lifecycle/test-timer-fire", eventName: "timer.scheduled", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkWorkflowTimer}, {name: "selected handler can arm workflow join timeout", fixture: "examples/routing/fan-in/barrier", eventName: "portfolio.setup", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkWorkflowJoinTimeout}, {name: "selected connect can create dynamic flow", fixture: "examples/routing/template-create-minted-key", eventName: "validation.triggered", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkDynamicFlowCreation}, {name: "selected connect can select or create missing dynamic flow", fixture: "examples/routing/template-select-or-create", eventName: "producer/account.requested", wantCode: selectedContractDeferredWorkOwnerUnavailable, wantCapability: selectedContractDeferredWorkDynamicFlowCreation}} {
		t.Run(test.name, func(t *testing.T) {
			_, db, _ := testutil.StartPostgres(t)
			pg := storetest.AdmitPostgresRuntimeStore(t, db)
			ctx := runForkTestContext(t)
			repoRoot := runForkExecutionRepoRoot(t)
			contractsRoot := filepath.Join(repoRoot, test.fixture)
			if test.fanOutBarrier {
				contractsRoot = canonicalrouting.CopyForkFanOutCarrier(t, false, true)
			}
			loader := admittedFixtureSelectedContractSourceLoader{RepoRoot: repoRoot, SourceRoot: contractsRoot, PlatformSpecPath: runtimecontracts.DefaultPlatformSpecFile(repoRoot)}
			sourceRunID := uuid.NewString()
			sourceEventID := uuid.NewString()
			at := time.Unix(1700002210, 0).UTC()
			entityID := uuid.NewString()
			seedSelectedExecutionSourceRunWithPrimaryRoute(t, pg, sourceRunID, entityID, sourceEventID, test.eventName, at, "test_entity", selectedExecutionTestAgentRoute(t, sourceRunID, "source-agent-that-must-not-route", "flow-a/1"), nil)
			sourceTimerID := ""
			if test.seedSourceTimer {
				sourceTimerID = uuid.NewString()
				ref := timeridentity.WorkflowTimerActivationRef{ActivationID: sourceTimerID, DeclarationKey: "test-node.check_timer", DeclarationRevision: "sha256:test-node-check-timer", Cause: timeridentity.WorkflowTimerActivationCauseInitial}
				if _, err := db.ExecContext(ctx, `
					INSERT INTO timers (
						timer_id, run_id, timer_name, entity_id, flow_scope_key, flow_instance_id, flow_instance, fire_event,
						fire_payload, routing_source, execution_mode, fire_at, owner_agent, owner_kind, task_type, status, created_at
					)
					VALUES (
						$1::uuid, $2::uuid, $3, $4::uuid, 'flow-a', '1', 'flow-a/1', 'timer.check',
						'{}'::jsonb, jsonb_build_object('kind', 'flow_owned_control', 'route', jsonb_build_object('flow_id', 'flow-a', 'flow_instance', 'flow-a/1', 'entity_id', $4::text)),
						'live', $5, 'test-node', 'system', 'workflow_timer', 'active', $6
					)
				`, sourceTimerID, sourceRunID, ref.TaskID(), entityID, at.Add(time.Hour), at); err != nil {
					t.Fatalf("seed source workflow timer: %v", err)
				}
			}
			captureSelectedExecutionSourceRevision(t, pg, sourceRunID)
			var sourceStatusBefore string
			if err := db.QueryRowContext(ctx, `SELECT status FROM runs WHERE run_id = $1::uuid`, sourceRunID).Scan(&sourceStatusBefore); err != nil {
				t.Fatalf("load source status before rejection: %v", err)
			}
			runtimeTopologyBefore := selectedContractDynamicRuntimeGlobalSnapshot(t, ctx, pg)
			owner := selectedContractExecutionOwnerForTest(t, pg)
			catalog := &observedSelectedJoinCatalog{SelectedContractForkLifecycle: owner.ports.fork, t: t, resolve: pg.ResolveAuthorActivityEventDescriptor}
			if test.fanOutBarrier {
				catalog.want = []string{"platform.join_complete"}
			} else if test.wantCapability == selectedContractDeferredWorkWorkflowJoinTimeout {
				catalog.want = []string{"platform.join_complete", "platform.join_timeout"}
			}
			owner.ports.fork = catalog
			result, err := executeLiveSelectedContractRunFork(ctx, SelectedContractExecutionRequest{SourceRunID: sourceRunID, At: sourceEventID, AllowSourceFreeze: true, Owner: owner, SourceLoader: loader, ContractSelection: runfork.RunForkContractSelection{Mode: runfork.RunForkContractSelectionModeSelectedContracts}, AgentRuntime: SelectedContractAgentRuntimeOptions{ProcessCapability: selectedContractTestProcessCapability(t, ctx, pg)}})
			failure, ok := runtimefailures.EnvelopeFromError(err)
			if err == nil || !ok || failure.Class != runtimefailures.ClassDependencyUnavailable || failure.Detail.Code != test.wantCode {
				t.Fatalf("ExecuteSelectedContractRunFork result=%#v error=%v, want %s rejection", result, err, test.wantCode)
			}
			capabilities, ok := failure.Detail.Attributes["capabilities"].([]string)
			if !ok || !slices.Contains(capabilities, test.wantCapability) {
				t.Fatalf("failure capabilities = %#v, want %q", failure.Detail.Attributes["capabilities"], test.wantCapability)
			}
			if result.Owner != runfork.RunForkSelectedContractExecutionOwner || result.Materialization.ForkRunID != "" {
				t.Fatalf("rejected result = %#v, want owner and no materialization", result)
			}
			if len(catalog.scopes) != 1 {
				t.Fatalf("selected preparation catalog registrations=%d, want one", len(catalog.scopes))
			}
			for _, scope := range catalog.scopes {
				if pg.AuthorActivityEventCatalogRegistered(scope) {
					t.Fatal("refused selected preparation leaked its catalog lease")
				}
			}
			assertSelectedContractDeferredWorkRejectionHasNoForkMutation(t, ctx, pg, sourceRunID)
			runtimeTopologyAfter := selectedContractDynamicRuntimeGlobalSnapshot(t, ctx, pg)
			for fact, want := range runtimeTopologyBefore {
				if got := runtimeTopologyAfter[fact]; got != want {
					t.Fatalf("deferred-work rejection changed global %s from %d to %d", fact, want, got)
				}
			}
			var sourceStatusAfter string
			if err := db.QueryRowContext(ctx, `SELECT status FROM runs WHERE run_id = $1::uuid`, sourceRunID).Scan(&sourceStatusAfter); err != nil {
				t.Fatalf("load source status after rejection: %v", err)
			}
			if sourceStatusAfter != sourceStatusBefore {
				t.Fatalf("source status changed from %q to %q during rejected deferred-work fork", sourceStatusBefore, sourceStatusAfter)
			}
			if sourceTimerID != "" {
				var status string
				if err := db.QueryRowContext(ctx, `SELECT status FROM timers WHERE timer_id = $1::uuid AND run_id = $2::uuid`, sourceTimerID, sourceRunID).Scan(&status); err != nil {
					t.Fatalf("load rejected source timer: %v", err)
				}
				if status != "active" {
					t.Fatalf("source timer status = %q, want active and untouched", status)
				}
			}
		})
	}
}

