		SELECT COUNT(*)
		FROM event_deliveries
		WHERE run_id = $1::uuid
		  AND event_id = $2::uuid
		  AND subscriber_type = 'node'
		  AND subscriber_id = $3
	`, result.Materialization.ForkRunID, forkEventID, sourceNodeID).Scan(&sourceNodeDeliveries); err != nil {
		t.Fatalf("count source node fork deliveries: %v", err)
	}
