	_, db, _ := testutil.StartPostgres(t)
	pg := storetest.AdmitPostgresRuntimeStore(t, db)
	ctx := context.Background()
	pinnedArtifact := sourceartifactfixture.New("agents.yaml", []byte("agents: {}\n# pinned-source\n"))
	otherArtifact := sourceartifactfixture.New("agents.yaml", []byte("agents: {}\n# other-source\n"))
	pinnedHash := pinnedArtifact.BundleHash()
	otherHash := otherArtifact.BundleHash()
	otherRunID := uuid.NewString()
	storetest.RequireRun(t, ctx, pg, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: uuid.NewString(), Artifact: pinnedArtifact})
	storetest.RequireRun(t, ctx, pg, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: otherRunID, State: storerunlifecycle.StatePaused, Artifact: otherArtifact})
	standingSource := mustServeTestPersistedSourceArtifactFact(otherHash)
	standingCtx := runStatusAuthorActivityContext(standingSource)
	standing, err := pg.ReconcileStandingService(standingCtx, runtimepipeline.StandingServiceCandidate{BindingEnabled: true, ServiceID: runtimeflowidentity.StandingServiceID("bundle-admission-proof"), FlowPath: "bundle-admission-proof", Source: standingSource})
	if err != nil {
		t.Fatalf("reconcile current standing bundle admission run: %v", err)
	}
	standingOtherRunID := standing.RunID
	if _, err := pg.TransitionActiveRun(standingCtx, storerunlifecycle.ActiveTransitionRequest{RunID: standingOtherRunID, State: storerunlifecycle.StatePaused}); err != nil {
		t.Fatalf("pause current standing bundle admission run: %v", err)
	}
	storetest.RequireRun(t, ctx, pg, storetest.RunFixture{Origin: storetest.ScenarioSetupOrigin(), RunID: uuid.NewString(), State: storerunlifecycle.StateCancelled, Artifact: otherArtifact})
	err = runbundle.AdmitPinnedSources(ctx, pg, pinnedHash, []string{pinnedHash})
	if err == nil {
		t.Fatal("enforceServePinnedBundleAdmissionForHashes error = nil, want pinned bundle_hash conflict")
	}
	got := err.Error()
	for _, want := range []string{"active non-standing run pinned bundle_hash conflict", pinnedHash, otherRunID, otherHash} {
		if !strings.Contains(got, want) {
			t.Fatalf("admission error = %q, want detail %q", got, want)
		}
	}
	if strings.Contains(got, standingOtherRunID) {
		t.Fatalf("pinned-hash admission claimed current standing run %s: %q", standingOtherRunID, got)
	}
	if err := runbundle.AdmitPinnedSources(ctx, pg, pinnedHash, nil); err != nil {
		t.Fatalf("unpinned admission = %v, want no pinned-context constraint", err)
	}
}

